INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-01', 'owner', 'audio-itops-a2-01', 'A2-B1 | 01. Morning Server Check & Handover (IT Ops)', 'Simple shift handover between two junior operators checking server status, alerts, and daily tickets (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-1', 'lesson-audio-itops-a2-01', 'owner', 0, 5.5, 'Good morning Ben, how was the night shift in the server room?', '[Ca sáng] Chào buổi sáng Ben, ca trực đêm ở phòng máy chủ thế nào?', 'night shift, server room', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-2', 'lesson-audio-itops-a2-01', 'owner', 5.5, 11, 'It was very quiet, and all main servers are running normally today.', '[Ca đêm] Rất yên tĩnh, và tất cả máy chủ chính hôm nay đều đang chạy bình thường.', 'quiet, running normally', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-3', 'lesson-audio-itops-a2-01', 'owner', 11, 16.5, 'Did we get any red alerts on the monitoring screen last night?', '[Ca sáng] Đêm qua màn hình giám sát có báo cảnh báo đỏ nào không?', 'alerts, monitoring screen', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-4', 'lesson-audio-itops-a2-01', 'owner', 16.5, 22.8, 'We had one yellow warning on mail server two around three in the morning.', '[Ca đêm] Ta có một cảnh báo vàng ở máy chủ thư số hai vào khoảng ba giờ sáng.', 'warning, mail server', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-5', 'lesson-audio-itops-a2-01', 'owner', 22.8, 28.3, 'What caused that warning, and did you need to restart the machine?', '[Ca sáng] Nguyên nhân cảnh báo là gì, cậu có cần khởi động lại máy không?', 'caused, restart', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-6', 'lesson-audio-itops-a2-01', 'owner', 28.3, 35, 'The memory was briefly high during a backup job, then it went back to normal.', '[Ca đêm] Bộ nhớ tăng cao một lúc khi chạy sao lưu, sau đó tự trở lại bình thường.', 'briefly, backup job, normal', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-7', 'lesson-audio-itops-a2-01', 'owner', 35, 40.5, 'Great, are there any open support tickets waiting for the morning team?', '[Ca sáng] Tốt quá, còn phiếu hỗ trợ nào đang mở chờ ca sáng xử lý không?', 'support tickets, waiting', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-8', 'lesson-audio-itops-a2-01', 'owner', 40.5, 46.8, 'Only two small printer requests, and I already wrote short notes in our logbook.', '[Ca đêm] Chỉ còn hai yêu cầu máy in nhỏ thôi, mình đã ghi chú ngắn vào sổ trực rồi.', 'requests, notes, logbook', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-9', 'lesson-audio-itops-a2-01', 'owner', 46.8, 52.7, 'Thanks for the clear handover, Ben; go home and get some good rest.', '[Ca sáng] Cảm ơn bàn giao rõ ràng nhé Ben; về nhà nghỉ ngơi cho khỏe đi.', 'handover, rest', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-02', 'owner', 'audio-itops-a2-02', 'A2-B1 | 02. Locked Account & Password Reset Call (IT Support)', 'Everyday IT helpdesk phone call helping a staff member unlock an account and set a safe password (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-1', 'lesson-audio-itops-a2-02', 'owner', 0, 5, 'Hello, IT helpdesk speaking; how can I help you this morning?', '[Helpdesk] Xin chào, bộ phận hỗ trợ IT nghe ạ; sáng nay tôi có thể giúp gì cho bạn?', 'helpdesk, speaking', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-2', 'lesson-audio-itops-a2-02', 'owner', 5, 11.3, 'Hi, I cannot sign in to my work email because my account is locked.', '[Nhân viên] Chào bạn, tôi không đăng nhập được email công ty vì tài khoản bị khóa rồi.', 'sign in, locked', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-3', 'lesson-audio-itops-a2-02', 'owner', 11.3, 17.6, 'Do not worry, I can unlock it for you in just a few minutes.', '[Helpdesk] Đừng lo, tôi có thể mở khóa giúp bạn chỉ trong vài phút.', 'unlock, a few minutes', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-4', 'lesson-audio-itops-a2-02', 'owner', 17.6, 23.1, 'First, could you please tell me your full name and employee number?', '[Helpdesk] Trước tiên, bạn vui lòng cho tôi biết họ tên đầy đủ và mã nhân viên nhé?', 'full name, employee number', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-5', 'lesson-audio-itops-a2-02', 'owner', 23.1, 29.4, 'Sure, my name is Claire Evans, and my number is four zero eight two.', '[Nhân viên] Được ạ, tôi tên Claire Evans, mã nhân viên là 4082.', 'number', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-6', 'lesson-audio-itops-a2-02', 'owner', 29.4, 35.3, 'Thank you Claire; I see five wrong password attempts on your login screen.', '[Helpdesk] Cảm ơn Claire; tôi thấy có năm lần nhập sai mật khẩu trên màn hình đăng nhập của bạn.', 'wrong password, attempts, login screen', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-7', 'lesson-audio-itops-a2-02', 'owner', 35.3, 41.2, 'Yes, my keyboard had caps lock turned on, so I typed it wrong.', '[Nhân viên] Đúng rồi, bàn phím tôi đang bật phím viết hoa nên tôi gõ sai.', 'keyboard, caps lock, typed', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-8', 'lesson-audio-itops-a2-02', 'owner', 41.2, 47.1, 'I have unlocked your account and sent a temporary link to your phone.', '[Helpdesk] Tôi đã mở khóa tài khoản và gửi một đường dẫn tạm thời tới điện thoại của bạn.', 'temporary link', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-9', 'lesson-audio-itops-a2-02', 'owner', 47.1, 53, 'Please choose a strong new password with letters and numbers, then try again.', '[Helpdesk] Bạn hãy chọn mật khẩu mới mạnh có cả chữ và số rồi thử đăng nhập lại nhé.', 'strong password, letters, numbers', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-03', 'owner', 'audio-itops-a2-03', 'A2-B1 | 03. Slow Office WiFi & Router Restart (IT Support)', 'Practical workplace call diagnosing slow internet on the third floor, checking cables, and restarting the router (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-1', 'lesson-audio-itops-a2-03', 'owner', 0, 5.9, 'Hi Sam, the internet on the third floor is very slow this afternoon.', '[Nhân viên] Chào Sam, mạng internet ở tầng ba chiều nay rất chậm.', 'third floor, slow', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-2', 'lesson-audio-itops-a2-03', 'owner', 5.9, 12.2, 'Is it slow only on your laptop, or are your colleagues having trouble too?', '[IT Support] Chỉ chậm trên máy tính xách tay của bạn hay đồng nghiệp cũng gặp trục trặc?', 'laptop, colleagues, having trouble', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-3', 'lesson-audio-itops-a2-03', 'owner', 12.2, 18.1, 'Everyone near the meeting room keeps losing their video calls every few minutes.', '[Nhân viên] Mọi người gần phòng họp đều cứ bị rớt cuộc gọi video sau vài phút.', 'meeting room, losing, video calls', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-4', 'lesson-audio-itops-a2-03', 'owner', 18.1, 24.4, 'Let me check the network panel; the wireless router on your floor looks busy.', '[IT Support] Để tôi kiểm tra bảng điều khiển mạng; bộ phát WiFi ở tầng bạn có vẻ đang quá tải.', 'network panel, wireless router, busy', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-5', 'lesson-audio-itops-a2-03', 'owner', 24.4, 31.1, 'Could you look at the small white box on the wall and check the lights?', '[IT Support] Bạn có thể nhìn hộp trắng nhỏ trên tường và kiểm tra các đèn báo giúp tôi không?', 'box on the wall, lights', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-6', 'lesson-audio-itops-a2-03', 'owner', 31.1, 37.4, 'The power light is green, but the network light is blinking orange very fast.', '[Nhân viên] Đèn nguồn màu xanh lá, nhưng đèn mạng đang nhấp nháy màu cam rất nhanh.', 'power light, blinking orange', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-7', 'lesson-audio-itops-a2-03', 'owner', 37.4, 44.1, 'I will restart that access point remotely now, so WiFi will drop for one minute.', '[IT Support] Tôi sẽ khởi động lại điểm phát sóng đó từ xa ngay, nên WiFi sẽ ngắt khoảng một phút.', 'access point, remotely, drop', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-8', 'lesson-audio-itops-a2-03', 'owner', 44.1, 50.4, 'The orange light turned solid green, and our pages are loading fast again now.', '[Nhân viên] Đèn cam chuyển sang xanh đứng yên rồi, các trang web cũng tải nhanh lại ngay.', 'solid green, loading fast', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-04', 'owner', 'audio-itops-a2-04', 'A2-B1 | 04. Daily Backup Check & Free Disk Space (IT Ops)', 'Simple operations chat about checking last night''s backup status and cleaning up old temporary files (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-1', 'lesson-audio-itops-a2-04', 'owner', 0, 5.9, 'Hey Anna, did the nightly backup finish safely on our main file server?', '[Ops] Chào Anna, bản sao lưu hằng đêm trên máy chủ tệp chính có hoàn tất an toàn không?', 'nightly backup, file server', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-2', 'lesson-audio-itops-a2-04', 'owner', 5.9, 12.2, 'Not completely; the backup stopped halfway because the storage drive ran out of space.', '[Junior Ops] Chưa hoàn toàn; bản sao lưu dừng giữa chừng vì ổ đĩa lưu trữ bị hết dung lượng.', 'stopped halfway, storage drive, ran out of space', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-3', 'lesson-audio-itops-a2-04', 'owner', 12.2, 18.5, 'Let us check which folder is taking up the most room on that drive.', '[Ops] Hãy kiểm tra xem thư mục nào đang chiếm nhiều chỗ nhất trên ổ đĩa đó.', 'folder, taking up, room', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-4', 'lesson-audio-itops-a2-04', 'owner', 18.5, 25.2, 'I see hundreds of old temporary files from last month still sitting inside the folder.', '[Junior Ops] Mình thấy hàng trăm tệp tạm cũ từ tháng trước vẫn còn nằm trong thư mục.', 'temporary files, sitting inside', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-5', 'lesson-audio-itops-a2-04', 'owner', 25.2, 31.1, 'Are any active users or programs still using those old files right now?', '[Ops] Có người dùng hay chương trình nào đang hoạt động còn dùng các tệp cũ đó không?', 'active users, programs', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-6', 'lesson-audio-itops-a2-04', 'owner', 31.1, 37.4, 'No, they are just finished export files that we only keep for seven days.', '[Junior Ops] Không, đó chỉ là các tệp xuất dữ liệu đã xong mà ta chỉ giữ lại bảy ngày.', 'export files, keep', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-7', 'lesson-audio-itops-a2-04', 'owner', 37.4, 43.7, 'Okay, delete the files older than two weeks and run the backup job again.', '[Ops] Được rồi, hãy xóa các tệp cũ hơn hai tuần rồi chạy lại tác vụ sao lưu nhé.', 'older than, backup job', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-8', 'lesson-audio-itops-a2-04', 'owner', 43.7, 50.4, 'We now have forty percent free space, and the new backup finished with zero errors.', '[Junior Ops] Giờ ta đã có 40% dung lượng trống, và bản sao lưu mới vừa chạy xong không lỗi nào.', 'free space, zero errors', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-05', 'owner', 'audio-itops-a2-05', 'A2-B1 | 05. Website Down? Basic First Checks (IT Ops)', 'Clear beginner IT Ops conversation walking through the first steps when a customer reports the company website is down (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-1', 'lesson-audio-itops-a2-05', 'owner', 0, 5.9, 'Tom, a client just messaged us saying our company website will not open.', '[Support] Tom ơi, một khách hàng vừa nhắn tin báo trang web công ty không mở được.', 'messaged, website', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-2', 'lesson-audio-itops-a2-05', 'owner', 5.9, 12.6, 'Let me test the address from my browser and check our public status page first.', '[Ops] Để mình thử mở địa chỉ từ trình duyệt và kiểm tra trang trạng thái công khai trước.', 'browser, status page', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-3', 'lesson-audio-itops-a2-05', 'owner', 12.6, 18.9, 'I see an error page too, so the problem is definitely on our side.', '[Ops] Mình cũng thấy trang báo lỗi, vậy chắc chắn sự cố nằm ở phía hệ thống của mình.', 'error page, definitely, on our side', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-4', 'lesson-audio-itops-a2-05', 'owner', 18.9, 25.2, 'Should we tell the manager right away, or check the web service logs first?', '[Support] Ta nên báo quản lý ngay lập tức, hay kiểm tra nhật ký dịch vụ web trước?', 'right away, service logs', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-5', 'lesson-audio-itops-a2-05', 'owner', 25.2, 31.9, 'Always check the service status first so we can share useful facts in our update.', '[Ops] Luôn kiểm tra trạng thái dịch vụ trước để ta chia sẻ thông tin hữu ích khi cập nhật.', 'service status, useful facts', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-6', 'lesson-audio-itops-a2-05', 'owner', 31.9, 38.6, 'Look here, the web service stopped five minutes ago right after a small setting change.', '[Ops] Nhìn đây này, dịch vụ web đã dừng năm phút trước ngay sau một thay đổi cài đặt nhỏ.', 'setting change', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-7', 'lesson-audio-itops-a2-05', 'owner', 38.6, 44.9, 'I will undo that setting change and start the web service back up cleanly.', '[Ops] Mình sẽ hoàn tác thay đổi cài đặt đó và khởi động lại dịch vụ web thật gọn.', 'undo, start back up', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-8', 'lesson-audio-itops-a2-05', 'owner', 44.9, 52, 'The homepage is online again, and I will reply to the client with a quick apology.', '[Support] Trang chủ lên mạng lại rồi, để mình nhắn trả lời xin lỗi nhanh cho khách hàng.', 'homepage, online, apology', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-06', 'owner', 'audio-itops-a2-06', 'A2-B1 | 06. Planning a Weekend Software Update (IT Ops)', 'Clear A2-B1 workplace chat planning a Saturday night server update, notifying users, saving a backup, and running quick tests (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-1', 'lesson-audio-itops-a2-06', 'owner', 0, 6.3, 'Hi Maya, when should we install the new security update on our office servers?', '[SysAdmin] Chào Maya, khi nào ta nên cài bản cập nhật bảo mật mới trên các máy chủ văn phòng?', 'install, security update', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-2', 'lesson-audio-itops-a2-06', 'owner', 6.3, 12.6, 'Saturday night at eleven is best because nobody is working in the office then.', '[Ops Lead] Tối thứ Bảy lúc mười một giờ là tốt nhất vì lúc đó không ai làm việc ở văn phòng.', 'nobody, working', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-3', 'lesson-audio-itops-a2-06', 'owner', 12.6, 18.5, 'How long will the systems be offline while the servers install and restart?', '[SysAdmin] Các hệ thống sẽ tạm ngưng bao lâu trong lúc máy chủ cài đặt và khởi động lại?', 'offline, restart', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-4', 'lesson-audio-itops-a2-06', 'owner', 18.5, 24.4, 'Usually around twenty minutes, though we should tell staff to expect thirty minutes.', '[Ops Lead] Thường khoảng hai mươi phút, nhưng ta nên báo nhân viên dự phòng ba mươi phút.', 'usually, expect', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-5', 'lesson-audio-itops-a2-06', 'owner', 24.4, 30.3, 'I will send a short reminder email to every department on Friday morning.', '[SysAdmin] Tôi sẽ gửi một email nhắc nhở ngắn cho mọi phòng ban vào sáng thứ Sáu.', 'reminder email, department', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-6', 'lesson-audio-itops-a2-06', 'owner', 30.3, 36.2, 'Please also make a fresh backup copy before you press the update button.', '[Ops Lead] Nhớ tạo thêm một bản sao lưu mới trước khi bạn bấm nút cập nhật nhé.', 'fresh backup copy, press', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-7', 'lesson-audio-itops-a2-06', 'owner', 36.2, 42.1, 'Of course, if anything breaks, we can restore the old version very quickly.', '[SysAdmin] Chắc chắn rồi, nếu có gì hỏng ta có thể khôi phục phiên bản cũ rất nhanh.', 'breaks, restore, old version', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-8', 'lesson-audio-itops-a2-06', 'owner', 42.1, 49.2, 'After the restart finishes, test login and email once, then post a green check in chat.', '[Ops Lead] Sau khi khởi động lại xong, hãy thử đăng nhập và email một lần rồi nhắn báo xanh vào nhóm chat nhé.', 'test login, post', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-01', 'owner', 'audio-itops-b1-01', 'B1 | 01. Investigating High Memory Usage on Production (IT Ops)', 'A 2-minute B1 IT Operations call tracking steady memory growth on a production server, moving traffic safely, and recovering after a release (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-1', 'lesson-audio-itops-b1-01', 'owner', 0, 7.1, 'Hello, I am calling because memory usage on application server two just passed eighty five percent.', '[Monitoring] Xin chào, tôi gọi vì mức dùng bộ nhớ trên máy chủ ứng dụng số hai vừa vượt qua 85%.', 'memory usage, application server', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-2', 'lesson-audio-itops-b1-01', 'owner', 7.1, 14.6, 'Thanks for telling me early; did the jump happen suddenly, or has it been going up slowly?', '[SysAdmin] Cảm ơn đã báo sớm; mức tăng đó xảy ra đột ngột hay đã tăng dần từ từ?', 'suddenly, going up slowly', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-3', 'lesson-audio-itops-b1-01', 'owner', 14.6, 20.9, 'Looking at the chart, memory started rising steadily right after last night’s software update.', '[Monitoring] Nhìn vào biểu đồ, bộ nhớ bắt đầu tăng đều ngay sau bản cập nhật phần mềm tối qua.', 'chart, rising steadily, software update', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-4', 'lesson-audio-itops-b1-01', 'owner', 20.9, 26.4, 'Are the other application servers showing the same rise on the dashboard?', '[SysAdmin] Các máy chủ ứng dụng khác có hiển thị mức tăng giống vậy trên bảng điều khiển không?', 'same rise, dashboard', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-5', 'lesson-audio-itops-b1-01', 'owner', 26.4, 33.1, 'Yes, server one is already at seventy eight percent, and server three is close behind.', '[Monitoring] Có, máy chủ số một đã ở mức 78%, còn máy chủ số ba cũng bám sát phía sau.', 'close behind', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-6', 'lesson-audio-itops-b1-01', 'owner', 33.1, 39.4, 'That clearly shows the new version is not freeing memory after finishing background tasks.', '[SysAdmin] Điều đó cho thấy rõ phiên bản mới không giải phóng bộ nhớ sau khi hoàn tất tác vụ nền.', 'clearly shows, freeing memory, background tasks', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-7', 'lesson-audio-itops-b1-01', 'owner', 39.4, 45.7, 'Are customers seeing slow page loads or error messages on the website right now?', '[SysAdmin] Khách hàng có đang gặp tình trạng tải trang chậm hay báo lỗi trên trang web lúc này không?', 'page loads, error messages', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-8', 'lesson-audio-itops-b1-01', 'owner', 45.7, 52.8, 'Not yet, response times are still normal, though we might hit the limit within two hours.', '[Monitoring] Chưa ạ, thời gian phản hồi vẫn bình thường, nhưng có thể chạm giới hạn trong vòng hai giờ nữa.', 'response times, hit the limit', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-9', 'lesson-audio-itops-b1-01', 'owner', 52.8, 59.5, 'Let us act before users notice; first, remove server two from the active load balancer.', '[SysAdmin] Hãy xử lý trước khi người dùng nhận ra; trước hết hãy gỡ máy chủ số hai khỏi bộ cân bằng tải đang chạy.', 'act before, load balancer', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-10', 'lesson-audio-itops-b1-01', 'owner', 59.5, 65.8, 'Should I wait for current user sessions to finish before stopping the application service?', '[Monitoring] Tôi có nên chờ các phiên người dùng hiện tại kết thúc trước khi dừng dịch vụ ứng dụng không?', 'user sessions, application service', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-11', 'lesson-audio-itops-b1-01', 'owner', 65.8, 72.5, 'Yes, give it thirty seconds to finish current connections so nobody loses their shopping cart.', '[SysAdmin] Đúng rồi, chờ ba mươi giây để hoàn tất các kết nối hiện tại để không ai bị mất giỏ hàng.', 'current connections, shopping cart', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-12', 'lesson-audio-itops-b1-01', 'owner', 72.5, 80.5, 'Server two has no active users now; do you want a quick memory report before I restart it?', '[Monitoring] Máy chủ số hai đã hết người dùng hoạt động; bạn có cần lấy báo cáo bộ nhớ nhanh trước khi tôi khởi động lại không?', 'active users, memory report', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-13', 'lesson-audio-itops-b1-01', 'owner', 80.5, 86.4, 'Please save the process list and memory report into our shared support folder.', '[SysAdmin] Nhớ lưu danh sách tiến trình và báo cáo bộ nhớ vào thư mục hỗ trợ dùng chung nhé.', 'process list, support folder', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-14', 'lesson-audio-itops-b1-01', 'owner', 86.4, 93.5, 'Both files are saved cleanly, and I am restarting the service on server two right now.', '[Monitoring] Cả hai tệp đã lưu gọn gàng, và tôi đang khởi động lại dịch vụ trên máy chủ số hai ngay đây.', 'saved cleanly', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-15', 'lesson-audio-itops-b1-01', 'owner', 93.5, 101, 'Once health checks pass, add server two back, then we will return to the previous stable version.', '[SysAdmin] Khi kiểm tra sức khỏe đạt, hãy đưa máy chủ số hai vào lại rồi ta sẽ quay về phiên bản ổn định trước đó.', 'health checks, stable version', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-16', 'lesson-audio-itops-b1-01', 'owner', 101, 107.7, 'Server two is healthy at thirty percent memory, and I am updating server one next.', '[Monitoring] Máy chủ số hai đã ổn định ở mức 30% bộ nhớ, tôi đang cập nhật tiếp máy chủ số một.', 'healthy, updating', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-17', 'lesson-audio-itops-b1-01', 'owner', 107.7, 115.2, 'I will share the memory report with the development team so they can fix the problem today.', '[SysAdmin] Tôi sẽ gửi báo cáo bộ nhớ cho đội phát triển để họ sửa lỗi trong hôm nay.', 'development team, fix the problem', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-18', 'lesson-audio-itops-b1-01', 'owner', 115.2, 123.2, 'All three servers are stable again, and I will keep watching the memory chart for the next hour.', '[Monitoring] Cả ba máy chủ đã ổn định trở lại, tôi sẽ tiếp tục theo dõi biểu đồ bộ nhớ trong một giờ tới.', 'keep watching, next hour', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-02', 'owner', 'audio-itops-b1-02', 'B1 | 02. Fixing a Broken VPN Tunnel for Branch Office (IT Ops)', 'A 2-minute B1 networking conversation fixing a disconnected site-to-site VPN tunnel, expired shared key, and network checks (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-1', 'lesson-audio-itops-b1-02', 'owner', 0, 6.3, 'Hello, staff at our Manchester office cannot open the internal finance system this morning.', '[Branch Support] Xin chào, nhân viên tại văn phòng Manchester sáng nay không mở được hệ thống tài chính nội bộ.', 'office, internal finance system', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-2', 'lesson-audio-itops-b1-02', 'owner', 6.3, 13, 'Can they still open normal public websites, or is the whole office internet connection down?', '[Network Eng] Họ vẫn mở được các trang web công khai bình thường, hay cả đường truyền internet văn phòng bị mất?', 'public websites, connection down', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-3', 'lesson-audio-itops-b1-02', 'owner', 13, 19.7, 'Public websites work fine, and office email loads quickly, so only internal tools are failing.', '[Branch Support] Các trang web công khai chạy tốt và email văn phòng tải nhanh, nên chỉ các công cụ nội bộ bị lỗi.', 'internal tools, failing', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-4', 'lesson-audio-itops-b1-02', 'owner', 19.7, 27.2, 'That sounds like a problem with the secure VPN tunnel between Manchester and our main data centre.', '[Network Eng] Nghe giống sự cố ở đường hầm VPN bảo mật giữa Manchester và trung tâm dữ liệu chính của ta.', 'VPN tunnel, data centre', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-5', 'lesson-audio-itops-b1-02', 'owner', 27.2, 33.9, 'Let me log into the main network gateway and check the tunnel status right away.', '[Network Eng] Để tôi đăng nhập vào cổng mạng chính và kiểm tra trạng thái đường hầm ngay lập tức.', 'network gateway, tunnel status', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-6', 'lesson-audio-itops-b1-02', 'owner', 33.9, 40.6, 'Yes, the tunnel went offline at six thirty this morning and keeps failing to reconnect.', '[Network Eng] Đúng rồi, đường hầm đã ngắt kết nối lúc sáu giờ ba mươi sáng nay và cứ kết nối lại thất bại.', 'went offline, reconnect', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-7', 'lesson-audio-itops-b1-02', 'owner', 40.6, 48.1, 'Did someone change the office firewall rules last night, or did the internet provider have an issue?', '[Branch Support] Có ai đổi quy tắc tường lửa văn phòng tối qua không, hay nhà mạng gặp sự cố?', 'firewall rules, internet provider', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-8', 'lesson-audio-itops-b1-02', 'owner', 48.1, 54.4, 'The gateway logs show a login error because the shared security key expired today.', '[Network Eng] Nhật ký cổng mạng báo lỗi đăng nhập vì khóa bảo mật dùng chung vừa hết hạn hôm nay.', 'shared security key, expired', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-9', 'lesson-audio-itops-b1-02', 'owner', 54.4, 60.3, 'I did not know those tunnel keys had a fixed yearly expiry date.', '[Branch Support] Tôi không biết các khóa đường hầm đó có ngày hết hạn cố định hằng năm.', 'yearly, expiry date', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-10', 'lesson-audio-itops-b1-02', 'owner', 60.3, 67.4, 'We change them every twelve months for security, and the reminder ticket was missed last week.', '[Network Eng] Chúng tôi đổi chúng mỗi mười hai tháng để bảo mật, và phiếu nhắc nhở tuần trước bị bỏ sót.', 'reminder ticket, missed', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-11', 'lesson-audio-itops-b1-02', 'owner', 67.4, 75.8, 'Can you update the key from the main office, or do I need to plug into the local router?', '[Branch Support] Bạn có thể cập nhật khóa từ văn phòng chính không, hay tôi cần cắm máy vào bộ định tuyến tại chỗ?', 'main office, local router', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-12', 'lesson-audio-itops-b1-02', 'owner', 75.8, 82.9, 'I can reach the branch router over our backup management line, so no cables are needed.', '[Network Eng] Tôi truy cập được bộ định tuyến chi nhánh qua đường quản trị dự phòng nên không cần cắm dây đâu.', 'backup management line, cables', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-13', 'lesson-audio-itops-b1-02', 'owner', 82.9, 89.6, 'I just created a fresh key and saved the matching settings on both gateway devices.', '[Network Eng] Tôi vừa tạo một khóa mới và lưu cấu hình khớp nhau trên cả hai thiết bị cổng mạng.', 'fresh key, matching settings', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-14', 'lesson-audio-itops-b1-02', 'owner', 89.6, 96.7, 'Now I am restarting the tunnel link; give it twenty seconds to build the secure connection.', '[Network Eng] Giờ tôi đang khởi động lại liên kết đường hầm; chờ khoảng hai mươi giây để thiết lập kết nối bảo mật.', 'restarting, secure connection', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-15', 'lesson-audio-itops-b1-02', 'owner', 96.7, 104.2, 'The status light just turned green on my screen, and test pings are returning in twelve milliseconds.', '[Network Eng] Đèn trạng thái vừa chuyển xanh trên màn hình của tôi, và lệnh ping thử phản hồi trong mười hai mili giây.', 'test pings, milliseconds', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-16', 'lesson-audio-itops-b1-02', 'owner', 104.2, 111.3, 'Let me ask the finance team to refresh their browsers and sign in again right now.', '[Branch Support] Để tôi nhờ nhóm tài chính tải lại trình duyệt và đăng nhập lại ngay lúc này.', 'refresh, sign in', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-17', 'lesson-audio-itops-b1-02', 'owner', 111.3, 118, 'They said the invoices are loading smoothly, and the shared network drive is visible again.', '[Branch Support] Họ báo hóa đơn tải mượt rồi, ổ đĩa mạng dùng chung cũng hiện lại bình thường.', 'loading smoothly, shared network drive', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-18', 'lesson-audio-itops-b1-02', 'owner', 118, 124.7, 'Great; I will set an automatic calendar reminder thirty days before next year’s key update.', '[Network Eng] Tuyệt; tôi sẽ đặt nhắc lịch tự động trước ba mươi ngày cho kỳ cập nhật khóa năm tới.', 'calendar reminder, key update', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-03', 'owner', 'audio-itops-b1-03', 'B1 | 03. Handling a Sudden Traffic Spike During Sales (IT Ops)', 'A 2-minute B1 cloud operations call handling a flash-sale traffic jump with extra web servers, page caching, and checkout checks (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-1', 'lesson-audio-itops-b1-03', 'owner', 0, 6.7, 'Hey, our marketing team just sent out a flash sale email and website traffic doubled.', '[Ops Lead] Chào bạn, đội marketing vừa gửi email khuyến mãi chớp nhoáng và lưu lượng web tăng gấp đôi rồi.', 'flash sale, traffic doubled', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-2', 'lesson-audio-itops-b1-03', 'owner', 6.7, 14.2, 'I saw the live chart jump a minute ago; how are the web servers handling the load?', '[Cloud Eng] Tôi thấy biểu đồ trực tiếp nhảy vọt một phút trước; các máy chủ web đang chịu tải thế nào?', 'live chart, handling the load', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-3', 'lesson-audio-itops-b1-03', 'owner', 14.2, 20.9, 'Average CPU across the web servers is around seventy five percent, and pages feel slower.', '[Ops Lead] CPU trung bình trên các máy chủ web khoảng 75%, và các trang web bắt đầu chậm hơn.', 'average CPU, slower', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-4', 'lesson-audio-itops-b1-03', 'owner', 20.9, 26.8, 'Did automatic scaling start adding extra server instances when CPU crossed seventy percent?', '[Cloud Eng] Hệ thống tự động mở rộng đã bắt đầu thêm máy chủ khi CPU vượt 70% chưa?', 'automatic scaling, extra server', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-5', 'lesson-audio-itops-b1-03', 'owner', 26.8, 34.3, 'It added two servers, but the maximum limit was set to six servers in our scaling rule.', '[Ops Lead] Nó đã thêm hai máy chủ, nhưng giới hạn tối đa trong quy tắc mở rộng chỉ đặt là sáu máy.', 'maximum limit, scaling rule', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-6', 'lesson-audio-itops-b1-03', 'owner', 34.3, 42.3, 'Let us raise that limit to ten servers right now so the system has plenty of extra space.', '[Cloud Eng] Hãy nâng giới hạn lên mười máy chủ ngay để hệ thống có nhiều khoảng trống dự phòng.', 'raise that limit, extra space', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-7', 'lesson-audio-itops-b1-03', 'owner', 42.3, 49.4, 'How long does each new web server take to start up and pass its health check?', '[Ops Lead] Mỗi máy chủ web mới mất bao lâu để khởi động và vượt qua bài kiểm tra sức khỏe?', 'start up, health check', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-8', 'lesson-audio-itops-b1-03', 'owner', 49.4, 56.1, 'About ninety seconds; two more servers are already starting and should join the balancer soon.', '[Cloud Eng] Khoảng chín mươi giây; hai máy chủ nữa đã bắt đầu chạy và sẽ sớm tham gia bộ cân bằng tải.', 'ninety seconds, join the balancer', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-9', 'lesson-audio-itops-b1-03', 'owner', 56.1, 62.8, 'What about the main database? Are heavy product searches putting too much pressure on it?', '[Ops Lead] Còn cơ sở dữ liệu chính thì sao? Lượt tìm kiếm sản phẩm nhiều có gây áp lực lớn lên nó không?', 'product searches, pressure', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-10', 'lesson-audio-itops-b1-03', 'owner', 62.8, 70.8, 'Database reads went up fast, so turning on longer page caching for product lists will help right away.', '[Cloud Eng] Lượt đọc database tăng nhanh, nên bật lưu đệm trang lâu hơn cho danh sách sản phẩm sẽ giúp ngay lập tức.', 'went up fast, page caching', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-11', 'lesson-audio-itops-b1-03', 'owner', 70.8, 77.5, 'Make sure we do not cache personal cart pages or payment checkout screens by mistake.', '[Ops Lead] Nhớ đảm bảo ta không vô tình lưu đệm trang giỏ hàng cá nhân hay màn hình thanh toán nhé.', 'by mistake, checkout screens', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-12', 'lesson-audio-itops-b1-03', 'owner', 77.5, 83.8, 'Of course, caching only applies to public product pages, images, and static banner files.', '[Cloud Eng] Chắc chắn rồi, bộ nhớ đệm chỉ áp dụng cho trang sản phẩm công khai, hình ảnh và tệp banner tĩnh.', 'product pages, static files', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-13', 'lesson-audio-itops-b1-03', 'owner', 83.8, 90.9, 'The new cache rule is live, and database read traffic just dropped by nearly forty percent.', '[Cloud Eng] Quy tắc bộ nhớ đệm mới đã chạy, lưu lượng đọc cơ sở dữ liệu vừa giảm gần 40%.', 'cache rule, dropped by nearly', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-14', 'lesson-audio-itops-b1-03', 'owner', 90.9, 98, 'Awesome, and all eight web servers are now green with average CPU back under fifty percent.', '[Ops Lead] Tuyệt vời, cả tám máy chủ web đều đã xanh với mức CPU trung bình quay về dưới 50%.', 'average CPU, under fifty percent', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-15', 'lesson-audio-itops-b1-03', 'owner', 98, 106, 'I also ran a quick test order on the checkout page and it finished in under one second.', '[Cloud Eng] Tôi cũng vừa chạy một đơn hàng thử trên trang thanh toán và hoàn tất trong chưa đầy một giây.', 'test order, finished', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-16', 'lesson-audio-itops-b1-03', 'owner', 106, 112.3, 'Let us ask marketing to tell operations one day ahead before future flash sales.', '[Ops Lead] Hãy nhờ đội marketing báo trước cho bộ phận vận hành một ngày trước các đợt khuyến mãi sau.', 'one day ahead, future', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-17', 'lesson-audio-itops-b1-03', 'owner', 112.3, 118.6, 'Good idea; that way we can prepare the servers and check our limits early.', '[Cloud Eng] Ý hay đấy; như vậy ta có thể chuẩn bị máy chủ trước và kiểm tra giới hạn từ sớm.', 'prepare the servers, check our limits', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-18', 'lesson-audio-itops-b1-03', 'owner', 118.6, 125.7, 'I will stay on the live dashboard until the sale ends and reduce the servers tonight.', '[Cloud Eng] Tôi sẽ theo dõi bảng điều khiển trực tiếp đến khi hết khuyến mãi rồi giảm bớt máy chủ tối nay.', 'live dashboard, reduce', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-04', 'owner', 'audio-itops-b1-04', 'B1 | 04. Resolving Email Delivery Delays & Queue Backlog (IT Ops)', 'A 2-minute B1 mail operations call fixing delayed customer emails, checking a stuck mail queue, stopping a noisy loop, and clearing deliveries (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-1', 'lesson-audio-itops-b1-04', 'owner', 0, 6.3, 'Hi, several customers called support because their order confirmation emails still have not arrived.', '[Helpdesk] Chào bạn, vài khách hàng gọi hỗ trợ vì email xác nhận đơn hàng vẫn chưa tới nơi.', 'order confirmation, arrived', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-2', 'lesson-audio-itops-b1-04', 'owner', 6.3, 13.4, 'Are those emails bouncing back with errors, or are they simply arriving much later than usual?', '[Mail Admin] Những email đó bị trả ngược báo lỗi hay chỉ đến chậm hơn bình thường nhiều?', 'bouncing back, later than usual', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-3', 'lesson-audio-itops-b1-04', 'owner', 13.4, 20.1, 'They are arriving about forty minutes late, and staff noticed internal messages are delayed too.', '[Helpdesk] Chúng đến trễ khoảng bốn mươi phút, và nhân viên cũng thấy thông báo nội bộ bị chậm theo.', 'delayed, internal messages', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-4', 'lesson-audio-itops-b1-04', 'owner', 20.1, 27.6, 'Let me check our outgoing mail server; wow, there are twelve thousand messages stuck in the queue.', '[Mail Admin] Để tôi kiểm tra máy chủ gửi thư; ôi, có mười hai nghìn thư đang bị kẹt trong hàng đợi.', 'outgoing mail server, stuck in the queue', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-5', 'lesson-audio-itops-b1-04', 'owner', 27.6, 33.5, 'Twelve thousand? Normally our busy morning queue only holds around two hundred emails.', '[Helpdesk] Mười hai nghìn cơ à? Bình thường hàng đợi giờ cao điểm buổi sáng chỉ khoảng hai trăm email thôi.', 'normally, holds around', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-6', 'lesson-audio-itops-b1-04', 'owner', 33.5, 40.2, 'Wait a second, most of these messages are coming from one single automatic reporting account.', '[Mail Admin] Khoan đã, phần lớn các thư này đều xuất phát từ duy nhất một tài khoản báo cáo tự động.', 'automatic reporting account', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-7', 'lesson-audio-itops-b1-04', 'owner', 40.2, 47.3, 'What is that account sending? It looks like the same five megabyte attachment repeated every second.', '[Mail Admin] Tài khoản đó đang gửi gì vậy? Trông như cùng một tệp đính kèm năm megabyte lặp lại mỗi giây.', 'attachment, repeated', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-8', 'lesson-audio-itops-b1-04', 'owner', 47.3, 54.4, 'Oh no, a scheduled billing script must be stuck in a retry loop after failing once.', '[Helpdesk] Ôi không, chắc một kịch bản xuất hóa đơn định kỳ bị kẹt vòng lặp gửi lại sau khi lỗi một lần.', 'scheduled script, retry loop', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-9', 'lesson-audio-itops-b1-04', 'owner', 54.4, 60.7, 'Exactly; it filled up all outgoing mail workers, blocking real customer emails behind it.', '[Mail Admin] Chính xác; nó chiếm kín toàn bộ luồng gửi thư, chặn hết email của khách hàng ở phía sau.', 'mail workers, blocking', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-10', 'lesson-audio-itops-b1-04', 'owner', 60.7, 67.8, 'First, I am pausing that automatic sender account so no new copy messages enter the queue.', '[Mail Admin] Trước hết tôi tạm khóa tài khoản gửi tự động đó để không có thêm thư trùng lặp vào hàng đợi.', 'pausing, copy messages', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-11', 'lesson-audio-itops-b1-04', 'owner', 67.8, 74.1, 'Can we clear out only those repeated report messages without deleting real customer emails?', '[Helpdesk] Mình có thể dọn riêng các thư báo cáo lặp lại đó mà không xóa nhầm email khách hàng thật không?', 'clear out, without deleting', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-12', 'lesson-audio-itops-b1-04', 'owner', 74.1, 81.2, 'Yes, I can filter the queue by sender address and remove only the stuck reporting job.', '[Mail Admin] Được chứ, tôi có thể lọc hàng đợi theo địa chỉ người gửi và chỉ gỡ tác vụ báo cáo bị kẹt.', 'filter the queue, sender address', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-13', 'lesson-audio-itops-b1-04', 'owner', 81.2, 87.5, 'Done, eleven thousand repeated messages are cleared, leaving only three hundred real customer emails.', '[Mail Admin] Xong rồi, mười một nghìn thư lặp đã được dọn, chỉ còn ba trăm email khách hàng thật.', 'real customer emails', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-14', 'lesson-audio-itops-b1-04', 'owner', 87.5, 94.6, 'Now I am pushing the mail queue so the server sends those waiting confirmations right away.', '[Mail Admin] Giờ tôi đẩy hàng đợi thư để máy chủ gửi ngay những thư xác nhận đang chờ.', 'pushing the mail queue, right away', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-15', 'lesson-audio-itops-b1-04', 'owner', 94.6, 101.7, 'I just tested a password reset email and it arrived in my inbox within three seconds.', '[Helpdesk] Tôi vừa thử một email đặt lại mật khẩu và nó vào hộp thư đến trong vòng ba giây.', 'arrived in my inbox', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-16', 'lesson-audio-itops-b1-04', 'owner', 101.7, 109.7, 'Great news; I will also tell the billing team to add a clear retry limit on their script.', '[Mail Admin] Tin tốt quá; tôi cũng sẽ báo nhóm thanh toán thêm giới hạn thử lại rõ ràng vào kịch bản của họ.', 'clear retry limit', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-17', 'lesson-audio-itops-b1-04', 'owner', 109.7, 118.1, 'Should we set a queue size alert so operations gets a message if more than five hundred emails wait?', '[Helpdesk] Ta có nên đặt cảnh báo kích thước hàng đợi để vận hành nhận tin khi có hơn năm trăm thư chờ không?', 'queue size alert', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-18', 'lesson-audio-itops-b1-04', 'owner', 118.1, 125.2, 'Yes, I am adding that monitoring rule right now along with a per minute sending limit.', '[Mail Admin] Có chứ, tôi đang thêm quy tắc giám sát đó ngay cùng với giới hạn số thư gửi mỗi phút.', 'monitoring rule, sending limit', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-05', 'owner', 'audio-itops-b1-05', 'B1 | 05. Cleaning Up Inodes & Stuck Background Jobs (IT Ops)', 'A 2-minute B1 Linux operations conversation solving a "no space left" error caused by 100% inode usage from tiny session files (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-1', 'lesson-audio-itops-b1-05', 'owner', 0, 8, 'Hi, I am confused because the web server says no space left, even though disk space looks fine.', '[Junior Ops] Chào bạn, mình hơi rối vì máy chủ web báo hết dung lượng dù dung lượng ổ đĩa trông vẫn ổn.', 'confused, no space left', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-2', 'lesson-audio-itops-b1-05', 'owner', 8, 14.3, 'How much free space did the normal disk command show when you checked it?', '[Linux Eng] Lệnh kiểm tra đĩa thông thường báo còn bao nhiêu dung lượng trống khi bạn xem?', 'disk command, free space', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-3', 'lesson-audio-itops-b1-05', 'owner', 14.3, 21.8, 'It showed thirty five percent free, about forty gigabytes available, yet nothing can create a new file.', '[Junior Ops] Nó hiện còn 35% trống, khoảng bốn mươi gigabyte sẵn dùng, vậy mà không gì tạo được tệp mới.', 'available, create a new file', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-4', 'lesson-audio-itops-b1-05', 'owner', 21.8, 28.5, 'Aha, that is a common Linux problem; please check the inode usage table right now.', '[Linux Eng] À ha, đó là một sự cố Linux rất hay gặp; bạn kiểm tra ngay bảng mức dùng inode đi.', 'common problem, inode usage', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-5', 'lesson-audio-itops-b1-05', 'owner', 28.5, 34.4, 'Oh wow, inode usage on the root drive is at one hundred percent.', '[Junior Ops] Ồ chà, mức sử dụng inode trên ổ đĩa gốc đang chạm đúng 100%.', 'root drive, one hundred percent', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-6', 'lesson-audio-itops-b1-05', 'owner', 34.4, 41.5, 'Could you quickly explain why a drive runs out of inodes while gigabytes are still free?', '[Junior Ops] Bạn giải thích nhanh giúp vì sao ổ đĩa hết inode trong khi vẫn còn thừa hàng chục gigabyte được không?', 'quickly explain, runs out of', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-7', 'lesson-audio-itops-b1-05', 'owner', 41.5, 49, 'Every single file needs one inode record, so millions of tiny files can use up every slot.', '[Linux Eng] Mỗi tệp đều cần một bản ghi inode, nên hàng triệu tệp nhỏ xíu có thể chiếm sạch mọi vị trí.', 'inode record, tiny files, use up', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-8', 'lesson-audio-itops-b1-05', 'owner', 49, 55.7, 'Let us find which folder holds the highest number of small files on this machine.', '[Linux Eng] Hãy tìm xem thư mục nào đang chứa số lượng tệp nhỏ nhiều nhất trên máy này.', 'folder, highest number', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-9', 'lesson-audio-itops-b1-05', 'owner', 55.7, 62.8, 'Found it; the temporary session folder has over two million tiny files created over three months.', '[Junior Ops] Tìm thấy rồi; thư mục phiên tạm có hơn hai triệu tệp nhỏ được tạo suốt ba tháng qua.', 'session folder, two million', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-10', 'lesson-audio-itops-b1-05', 'owner', 62.8, 69.1, 'Why did our nightly cleanup job stop clearing old session files three months ago?', '[Linux Eng] Tại sao tác vụ dọn dẹp hằng đêm lại ngừng xóa các tệp phiên cũ từ ba tháng trước?', 'nightly cleanup job', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-11', 'lesson-audio-itops-b1-05', 'owner', 69.1, 76.6, 'Let me check the scheduled task file; someone turned off the cleanup line during testing and forgot.', '[Junior Ops] Để mình kiểm tra tệp tác vụ định kỳ; có ai đó đã tắt dòng dọn dẹp lúc thử nghiệm rồi quên bật lại.', 'scheduled task, turned off, forgot', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-12', 'lesson-audio-itops-b1-05', 'owner', 76.6, 84.1, 'Good catch; remember not to run a simple delete all command on two million files at once.', '[Linux Eng] Phát hiện tốt đấy; nhớ đừng chạy lệnh xóa tất cả thông thường trên hai triệu tệp cùng lúc nhé.', 'good catch, at once', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-13', 'lesson-audio-itops-b1-05', 'owner', 84.1, 90, 'Right, because the shell command will fail with a too many files error.', '[Junior Ops] Đúng rồi, vì lệnh shell sẽ báo lỗi quá nhiều tệp.', 'shell command, too many files', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-14', 'lesson-audio-itops-b1-05', 'owner', 90, 98.8, 'Use the find command to delete in small groups for files older than two days so active sessions stay safe.', '[Linux Eng] Hãy dùng lệnh find để xóa theo từng nhóm nhỏ cho tệp cũ hơn hai ngày để các phiên đang chạy vẫn an toàn.', 'small groups, older than, stay safe', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-15', 'lesson-audio-itops-b1-05', 'owner', 98.8, 106.3, 'It is running smoothly now, and inode usage already dropped from one hundred down to twenty percent.', '[Junior Ops] Lệnh đang chạy mượt rồi, mức dùng inode vừa giảm từ 100% xuống còn 20%.', 'running smoothly, dropped', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-16', 'lesson-audio-itops-b1-05', 'owner', 106.3, 113.8, 'Next, turn the nightly cleanup schedule back on and check that the web app writes logs cleanly.', '[Linux Eng] Tiếp theo hãy bật lại lịch dọn dẹp hằng đêm và kiểm tra xem ứng dụng web ghi log ổn chưa.', 'turn back on, writes logs', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-17', 'lesson-audio-itops-b1-05', 'owner', 113.8, 121.8, 'Application logs are writing again, and I added an inode alert at eighty percent to our monitoring tool.', '[Junior Ops] Log ứng dụng đã ghi trở lại, và mình đã thêm cảnh báo inode ở mức 80% vào công cụ giám sát.', 'inode alert, monitoring tool', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-18', 'lesson-audio-itops-b1-05', 'owner', 121.8, 128.5, 'Nice work today; checking inodes is a very useful habit every Linux engineer should know.', '[Linux Eng] Hôm nay làm tốt lắm; kiểm tra inode là thói quen rất hữu ích mà kỹ sư Linux nào cũng nên biết.', 'useful habit', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-06', 'owner', 'audio-itops-b1-06', 'B1 | 06. Planning a Safe Database Migration Weekend (IT Ops)', 'A 2-minute B1 planning conversation preparing a customer database move to a larger server with test runs, checks, and a backup plan (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-1', 'lesson-audio-itops-b1-06', 'owner', 0, 5.5, 'Good afternoon, let us finish our checklist for Saturday’s customer database migration.', '[Project Lead] Chào buổi chiều, cùng chốt danh sách kiểm tra cho đợt chuyển cơ sở dữ liệu khách hàng thứ Bảy này nhé.', 'checklist, database migration', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-2', 'lesson-audio-itops-b1-06', 'owner', 5.5, 12.6, 'Sure, our current server is almost full, so moving to the new machine is very important.', '[DBA] Chắc chắn rồi, máy chủ hiện tại gần đầy rồi nên chuyển sang máy mới là rất quan trọng.', 'almost full, very important', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-3', 'lesson-audio-itops-b1-06', 'owner', 12.6, 18.5, 'How much total downtime should we tell customers to expect on Saturday night?', '[Project Lead] Chúng ta nên báo khách hàng dự kiến tổng thời gian tạm ngưng là bao lâu vào tối thứ Bảy?', 'downtime, expect', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-4', 'lesson-audio-itops-b1-06', 'owner', 18.5, 26.5, 'In our test run on staging yesterday, the final switch took twenty five minutes from start to finish.', '[DBA] Trong lần chạy thử trên staging hôm qua, bước chuyển cuối cùng mất hai mươi lăm phút từ đầu đến cuối.', 'test run, final switch', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-5', 'lesson-audio-itops-b1-06', 'owner', 26.5, 33.2, 'Let us share a one hour maintenance window so we have plenty of extra time.', '[Project Lead] Hãy thông báo khung bảo trì một tiếng để ta có nhiều thời gian dự phòng.', 'maintenance window, extra time', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-6', 'lesson-audio-itops-b1-06', 'owner', 33.2, 39.9, 'How are we copying such a large database without keeping the website offline for hours?', '[Project Lead] Ta sao chép cơ sở dữ liệu lớn như vậy bằng cách nào mà không để trang web ngừng hoạt động hàng giờ?', 'copying, offline for hours', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-7', 'lesson-audio-itops-b1-06', 'owner', 39.9, 47, 'We already set up live syncing, so the new server gets every change in real time.', '[DBA] Tụi mình đã thiết lập đồng bộ trực tiếp rồi, nên máy chủ mới nhận mọi thay đổi theo thời gian thực.', 'live syncing, real time', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-8', 'lesson-audio-itops-b1-06', 'owner', 47, 55.4, 'That means during maintenance we only pause writes briefly and wait for the last few rows to catch up.', '[DBA] Nghĩa là lúc bảo trì ta chỉ tạm dừng ghi dữ liệu một lát rồi chờ vài dòng cuối đồng bộ kịp.', 'pause writes, catch up', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-9', 'lesson-audio-itops-b1-06', 'owner', 55.4, 62.5, 'Once the data matches completely, how will we check that nothing was missed during the move?', '[Project Lead] Khi dữ liệu khớp hoàn toàn, ta sẽ kiểm tra thế nào để chắc không sót gì trong quá trình chuyển?', 'matches completely, missed', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-10', 'lesson-audio-itops-b1-06', 'owner', 62.5, 70, 'I wrote a check script that compares table row counts and data checks across all main tables.', '[DBA] Tôi đã viết một kịch bản kiểm tra so sánh số dòng và kiểm tra dữ liệu trên mọi bảng chính.', 'check script, row counts', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-11', 'lesson-audio-itops-b1-06', 'owner', 70, 77.1, 'And what happens if our application servers show unexpected errors right after using the new database?', '[Project Lead] Còn chuyện gì xảy ra nếu các máy chủ ứng dụng báo lỗi bất ngờ ngay sau khi dùng database mới?', 'unexpected errors', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-12', 'lesson-audio-itops-b1-06', 'owner', 77.1, 84.2, 'We will keep the old database server safe and online in read only mode all weekend.', '[DBA] Ta sẽ giữ nguyên máy chủ database cũ an toàn và chạy ở chế độ chỉ đọc suốt cuối tuần.', 'read only mode', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-13', 'lesson-audio-itops-b1-06', 'owner', 84.2, 92.2, 'If any important quick test fails within fifteen minutes, we simply point traffic back to the old server.', '[DBA] Nếu bất kỳ bài kiểm thử nhanh quan trọng nào lỗi trong mười lăm phút, ta chỉ việc trỏ lưu lượng về lại máy cũ.', 'quick test, point traffic back', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-14', 'lesson-audio-itops-b1-06', 'owner', 92.2, 99.7, 'Have we checked firewall rules and login passwords so every app server can reach the new host?', '[Project Lead] Ta đã kiểm tra quy tắc tường lửa và mật khẩu đăng nhập để mọi máy chủ ứng dụng nối được tới máy mới chưa?', 'login passwords, reach the new host', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-15', 'lesson-audio-itops-b1-06', 'owner', 99.7, 106, 'Yes, we tested network access and login permissions from every production server earlier today.', '[DBA] Rồi ạ, đầu ngày hôm nay ta đã thử kết nối mạng và quyền đăng nhập từ từng máy chủ production.', 'network access, login permissions', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-16', 'lesson-audio-itops-b1-06', 'owner', 106, 111.9, 'Also remember to take a fresh full backup right before pausing production writes.', '[Project Lead] Cũng nhớ tạo một bản sao lưu đầy đủ mới ngay trước khi tạm dừng ghi trên production nhé.', 'fresh full backup', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-17', 'lesson-audio-itops-b1-06', 'owner', 111.9, 119, 'It is step two on our guide, and two engineers will double check every command together.', '[DBA] Đó là bước hai trong hướng dẫn rồi, và hai kỹ sư sẽ cùng kiểm tra chéo từng câu lệnh.', 'guide, double check', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-18', 'lesson-audio-itops-b1-06', 'owner', 119, 126.5, 'Everything looks well prepared; let us meet on the team call at ten forty five Saturday night.', '[Project Lead] Mọi thứ chuẩn bị rất chu đáo rồi; hẹn gặp nhau trên cuộc gọi nhóm lúc mười giờ bốn lăm tối thứ Bảy nhé.', 'well prepared, team call', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-07', 'owner', 'audio-itops-b1-07', 'B1 | 07. Responding to a Phishing Email & Account Check (IT Ops)', 'A 2-minute B1 security operations phone call helping an employee who clicked a fake invoice link, signing out sessions, blocking the site, and turning on two-factor login (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-1', 'lesson-audio-itops-b1-07', 'owner', 0, 8.4, 'Hello security desk, I think I just made a mistake and clicked a strange invoice link in my email.', '[Staff] Xin chào bộ phận bảo mật, tôi nghĩ mình vừa lỡ tay bấm vào một đường dẫn hóa đơn lạ trong email.', 'made a mistake, strange invoice link', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-2', 'lesson-audio-itops-b1-07', 'owner', 8.4, 15.5, 'Thank you for calling right away; reporting it fast is the best thing you could do.', '[Security Ops] Cảm ơn bạn đã gọi ngay lập tức; báo sớm là điều tốt nhất bạn có thể làm lúc này.', 'reporting it fast', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-3', 'lesson-audio-itops-b1-07', 'owner', 15.5, 23.5, 'Tell me calmly what happened after you clicked the link; did a login page ask for your password?', '[Security Ops] Hãy kể bình tĩnh chuyện gì xảy ra sau khi bạn bấm link; có trang đăng nhập nào đòi mật khẩu không?', 'calmly, login page', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-4', 'lesson-audio-itops-b1-07', 'owner', 23.5, 32.7, 'Yes, it looked just like our company portal, so I typed my work email and password before seeing the strange address.', '[Staff] Có, nó giống hệt cổng nội bộ công ty nên tôi đã nhập email và mật khẩu trước khi thấy địa chỉ lạ.', 'company portal, strange address', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-5', 'lesson-audio-itops-b1-07', 'owner', 32.7, 39.8, 'Okay, do not worry; let me check your account login history and active sessions right now.', '[Security Ops] Được rồi, đừng lo; để tôi kiểm tra lịch sử đăng nhập và các phiên đang mở của bạn ngay đây.', 'login history, active sessions', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-6', 'lesson-audio-itops-b1-07', 'owner', 39.8, 48.6, 'I see a login attempt from an unknown city two minutes ago, so we need to lock it down fast.', '[Security Ops] Tôi thấy một lượt đăng nhập từ một thành phố lạ hai phút trước, nên ta cần khóa chặt ngay.', 'unknown city, lock it down', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-7', 'lesson-audio-itops-b1-07', 'owner', 48.6, 56.1, 'First, I am signing out all active sessions on every device and resetting your password right now.', '[Security Ops] Trước tiên, tôi đăng xuất toàn bộ phiên đang hoạt động trên mọi thiết bị và đặt lại mật khẩu ngay.', 'signing out, active sessions', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-8', 'lesson-audio-itops-b1-07', 'owner', 56.1, 62, 'Did the attacker open any shared files or forward emails from my mailbox?', '[Staff] Kẻ tấn công có kịp mở tệp dùng chung nào hay chuyển tiếp email từ hộp thư của tôi không?', 'attacker, forward emails, mailbox', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-9', 'lesson-audio-itops-b1-07', 'owner', 62, 69.1, 'Good news, the activity log shows zero file downloads and no hidden forwarding rules were added.', '[Security Ops] Tin tốt là nhật ký hoạt động không ghi nhận lượt tải tệp nào và cũng chưa có quy tắc chuyển tiếp ẩn.', 'activity log, forwarding rules', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-10', 'lesson-audio-itops-b1-07', 'owner', 69.1, 75.4, 'I am so glad; did the website download any strange file onto my laptop?', '[Staff] Thật nhẹ nhõm quá; trang web đó có tải tệp lạ nào xuống máy tính xách tay của tôi không?', 'glad, strange file', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-11', 'lesson-audio-itops-b1-07', 'owner', 75.4, 82.5, 'Our antivirus scan shows your laptop is clean, though I will run one more quick check.', '[Security Ops] Công cụ diệt virus báo máy bạn sạch, nhưng tôi vẫn sẽ chạy thêm một lượt quét nhanh.', 'antivirus scan, quick check', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-12', 'lesson-audio-itops-b1-07', 'owner', 82.5, 90.9, 'Please forward the fake email to our security inbox so we can block that website for the whole company.', '[Security Ops] Bạn hãy chuyển tiếp thư giả đó tới hộp thư bảo mật để ta chặn trang web đó trên toàn công ty.', 'fake email, whole company', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-13', 'lesson-audio-itops-b1-07', 'owner', 90.9, 98.9, 'I am forwarding it now; do I also need to change my password on any other work apps?', '[Staff] Tôi đang chuyển tiếp đây; tôi có cần đổi mật khẩu trên ứng dụng công việc nào khác không?', 'change my password', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-14', 'lesson-audio-itops-b1-07', 'owner', 98.9, 106.9, 'Only if you used the same password anywhere else; always keep your work password different from other accounts.', '[Security Ops] Chỉ khi bạn dùng lại đúng mật khẩu đó ở nơi khác; hãy luôn giữ mật khẩu công việc khác với các tài khoản khác.', 'same password, different', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-15', 'lesson-audio-itops-b1-07', 'owner', 106.9, 115.3, 'Next, let us turn on two factor login on your phone so a stolen password alone cannot sign in.', '[Security Ops] Tiếp theo hãy bật đăng nhập hai bước trên điện thoại để riêng mật khẩu bị lộ không thể đăng nhập.', 'two factor login, stolen password', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-16', 'lesson-audio-itops-b1-07', 'owner', 115.3, 122.8, 'I just scanned the setup code in my phone app and typed in the six digit code.', '[Staff] Tôi vừa quét mã cài đặt trong ứng dụng điện thoại và nhập mã sáu chữ số rồi.', 'setup code, six digit code', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-17', 'lesson-audio-itops-b1-07', 'owner', 122.8, 131.2, 'Your account is safe again, and I have already blocked the sender and removed the email from other inboxes.', '[Security Ops] Tài khoản của bạn đã an toàn trở lại, và tôi đã chặn người gửi cũng như gỡ thư đó khỏi hộp thư người khác.', 'blocked the sender, removed', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-18', 'lesson-audio-itops-b1-07', 'owner', 131.2, 138.7, 'Thanks so much for your help; I will always check the sender address carefully from now on.', '[Staff] Cảm ơn bạn rất nhiều vì đã hỗ trợ; từ giờ tôi sẽ luôn kiểm tra kỹ địa chỉ người gửi.', 'sender address, carefully', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-08', 'owner', 'audio-itops-b1-08', 'B1 | 08. Fixing Broken Scheduled Backups & Storage Alerts (IT Ops)', 'A 2-minute B1 operations call fixing three failed overnight backup jobs, expired cloud storage keys, manual upload, and restore tests (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-1', 'lesson-audio-itops-b1-08', 'owner', 0, 8.4, 'Good morning, I saw on the daily report that our file server backup failed three nights in a row.', '[Shift Operator] Chào buổi sáng, mình thấy trên báo cáo hằng ngày là bản sao lưu máy chủ tệp lỗi ba đêm liên tiếp rồi.', 'daily report, three nights in a row', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-2', 'lesson-audio-itops-b1-08', 'owner', 8.4, 15.9, 'Three nights? Why did the monitoring board only show a yellow warning instead of a red alert?', '[Backup Eng] Ba đêm cơ à? Sao bảng giám sát chỉ hiện cảnh báo vàng thay vì cảnh báo đỏ vậy?', 'monitoring board, instead of', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-3', 'lesson-audio-itops-b1-08', 'owner', 15.9, 23.9, 'The alert rule only turns red after five failures, which feels much too late for important company files.', '[Shift Operator] Quy tắc cảnh báo chỉ chuyển đỏ sau năm lần lỗi, như vậy quá trễ đối với dữ liệu công ty quan trọng.', 'too late, company files', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-4', 'lesson-audio-itops-b1-08', 'owner', 23.9, 31.9, 'You are completely right; let us fix the broken backup first and change that alert rule right after.', '[Backup Eng] Bạn nói hoàn toàn đúng; trước hết hãy sửa bản sao lưu hỏng rồi đổi quy tắc cảnh báo ngay sau đó.', 'broken backup, alert rule', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-5', 'lesson-audio-itops-b1-08', 'owner', 31.9, 40.3, 'I opened last night’s backup log, and the job failed right at the start with an access denied message.', '[Shift Operator] Mình mở nhật ký sao lưu đêm qua, tác vụ lỗi ngay từ đầu với thông báo bị từ chối truy cập.', 'access denied', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-6', 'lesson-audio-itops-b1-08', 'owner', 40.3, 46.6, 'Access denied usually means our cloud storage key expired or someone changed folder permissions.', '[Backup Eng] Từ chối truy cập thường có nghĩa khóa lưu trữ đám mây đã hết hạn hoặc có ai đổi quyền thư mục.', 'cloud storage key, permissions', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-7', 'lesson-audio-itops-b1-08', 'owner', 46.6, 53.7, 'Let me check the service account page; yes, the backup access key expired on Monday evening.', '[Backup Eng] Để tôi xem trang tài khoản dịch vụ; đúng rồi, khóa truy cập sao lưu vừa hết hạn tối thứ Hai.', 'service account, access key', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-8', 'lesson-audio-itops-b1-08', 'owner', 53.7, 61.2, 'Are all our local backup copies from the past week still safe on the office storage server?', '[Shift Operator] Toàn bộ bản sao lưu nội bộ tuần qua vẫn an toàn trên máy chủ lưu trữ văn phòng chứ?', 'local backup copies, storage server', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-9', 'lesson-audio-itops-b1-08', 'owner', 61.2, 68.3, 'Yes, local backups worked fine; only the cloud backup upload failed because of the expired key.', '[Backup Eng] Có, bản sao lưu nội bộ vẫn chạy tốt; chỉ bước tải lên đám mây bị lỗi do khóa hết hạn.', 'cloud backup upload', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-10', 'lesson-audio-itops-b1-08', 'owner', 68.3, 75.8, 'I am creating a new service key now and updating the saved key inside our backup tool.', '[Backup Eng] Tôi đang tạo khóa dịch vụ mới và cập nhật khóa đã lưu bên trong công cụ sao lưu.', 'saved key, backup tool', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-11', 'lesson-audio-itops-b1-08', 'owner', 75.8, 83.3, 'Should we wait until midnight to see if it works, or run a manual backup right now?', '[Shift Operator] Ta có nên đợi tới nửa đêm xem có chạy không, hay chạy sao lưu thủ công ngay bây giờ?', 'manual backup', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-12', 'lesson-audio-itops-b1-08', 'owner', 83.3, 91.3, 'Never wait until midnight after three failures; let us start a quick upload of new files right away.', '[Backup Eng] Đừng bao giờ đợi tới nửa đêm sau ba lần lỗi; hãy chạy tải lên nhanh các tệp mới ngay lập tức.', 'quick upload, right away', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-13', 'lesson-audio-itops-b1-08', 'owner', 91.3, 97.2, 'The upload started cleanly and is sending files at forty megabytes per second.', '[Shift Operator] Quá trình tải lên đã chạy gọn và đang gửi tệp ở tốc độ bốn mươi megabyte mỗi giây.', 'sending files, per second', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-14', 'lesson-audio-itops-b1-08', 'owner', 97.2, 102.7, 'Since it only uploads changed files, it should finish within five minutes.', '[Backup Eng] Vì chỉ tải lên các tệp đã thay đổi nên chắc sẽ xong trong vòng năm phút thôi.', 'changed files, within five minutes', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-15', 'lesson-audio-itops-b1-08', 'owner', 102.7, 110.7, 'It just finished with zero errors! Let us also restore one test folder to staging to be sure.', '[Shift Operator] Vừa chạy xong không một lỗi nào! Mình cũng khôi phục thử một thư mục mẫu lên staging cho chắc nhé.', 'to be sure, staging', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-16', 'lesson-audio-itops-b1-08', 'owner', 110.7, 115.7, 'The test restore worked and every document opened with no errors.', '[Backup Eng] Bản khôi phục thử đã chạy tốt và mọi tài liệu đều mở được không có lỗi nào.', 'test restore, no errors', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-17', 'lesson-audio-itops-b1-08', 'owner', 115.7, 124.5, 'Now I am updating the alert rule so even a single missed backup sends a red ticket the next morning.', '[Backup Eng] Giờ tôi cập nhật quy tắc cảnh báo để chỉ cần lỡ một lần sao lưu là gửi phiếu đỏ ngay sáng hôm sau.', 'alert rule, missed backup', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-18', 'lesson-audio-itops-b1-08', 'owner', 124.5, 133.3, 'Thanks a lot, I will add a calendar reminder to change the storage key before it expires in three months.', '[Shift Operator] Cảm ơn nhiều nhé, mình sẽ thêm nhắc lịch đổi khóa lưu trữ trước khi hết hạn trong ba tháng tới.', 'calendar reminder, in three months', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-09', 'owner', 'audio-itops-b1-09', 'B1 | 09. Troubleshooting Slow API Calls & Timeout Errors (IT Ops)', 'A 2-minute B1 incident call tracing mobile app timeouts through API gateway logs to a slow payment partner and switching to a backup service (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-1', 'lesson-audio-itops-b1-09', 'owner', 0, 6.7, 'Hi, mobile app users are reporting loading spinners and timeout errors when paying for orders.', '[App Support] Chào bạn, người dùng ứng dụng di động đang báo vòng xoay tải mãi và lỗi quá thời gian khi thanh toán đơn hàng.', 'loading spinners, timeout errors', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-2', 'lesson-audio-itops-b1-09', 'owner', 6.7, 15.5, 'Let me open the API gateway dashboard; yes, the error rate on the payment endpoint just rose to twelve percent.', '[SRE] Để tôi mở bảng điều khiển cổng API; đúng rồi, tỷ lệ lỗi trên điểm cuối thanh toán vừa tăng lên 12%.', 'API gateway, error rate, endpoint', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-3', 'lesson-audio-itops-b1-09', 'owner', 15.5, 21.8, 'Are other mobile features like browsing products or viewing order history still working fast?', '[SRE] Các tính năng di động khác như xem sản phẩm hay lịch sử đơn hàng vẫn chạy nhanh chứ?', 'order history, browsing products', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-4', 'lesson-audio-itops-b1-09', 'owner', 21.8, 28.9, 'Yes, everything else responds in under half a second; only the checkout payment call is hanging.', '[App Support] Có, mọi thứ khác phản hồi dưới nửa giây; chỉ đúng lời gọi thanh toán lúc đặt hàng bị treo.', 'responds, hanging', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-5', 'lesson-audio-itops-b1-09', 'owner', 28.9, 37.7, 'Let us check the request logs to see whether the delay is inside our own code or an outside partner.', '[SRE] Hãy kiểm tra nhật ký yêu cầu xem độ trễ nằm trong mã của ta hay ở phía đối tác bên ngoài.', 'request logs, outside partner', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-6', 'lesson-audio-itops-b1-09', 'owner', 37.7, 46.5, 'Look at the time details: our internal service finishes in twenty milliseconds, then waits thirty seconds for the bank API.', '[SRE] Nhìn chi tiết thời gian này: dịch vụ nội bộ của ta xử lý xong trong 20 mili giây, rồi chờ 30 giây cho API ngân hàng.', 'time details, internal service', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-7', 'lesson-audio-itops-b1-09', 'owner', 46.5, 53.2, 'Thirty seconds is way too long! Let me check the payment partner’s public status page.', '[App Support] Ba mươi giây là quá lâu rồi! Để tôi kiểm tra trang trạng thái công khai của đối tác thanh toán.', 'payment partner, public status page', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-8', 'lesson-audio-itops-b1-09', 'owner', 53.2, 59.5, 'They just posted an incident notice saying their European payment gateway is running slowly.', '[App Support] Họ vừa đăng thông báo sự cố nói rằng cổng thanh toán châu Âu của họ đang chạy chậm.', 'incident notice, running slowly', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-9', 'lesson-audio-itops-b1-09', 'owner', 59.5, 67, 'Because our timeout was set to thirty seconds, waiting calls are keeping all our payment workers busy.', '[SRE] Vì thời gian chờ của ta đặt tới ba mươi giây, các cuộc gọi đang chờ đã làm bận hết toàn bộ luồng xử lý thanh toán.', 'keeping busy, payment workers', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-10', 'lesson-audio-itops-b1-09', 'owner', 67, 74.1, 'Can we lower the timeout to six seconds and show a polite retry message to users?', '[App Support] Ta có thể hạ thời gian chờ xuống sáu giây và hiện thông báo mời người dùng thử lại lịch sự không?', 'lower the timeout, retry message', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-11', 'lesson-audio-itops-b1-09', 'owner', 74.1, 80.8, 'Even better, we also have a backup payment service set up and ready for traffic.', '[SRE] Tốt hơn nữa, ta còn cấu hình sẵn một dịch vụ thanh toán dự phòng và sẵn sàng nhận lưu lượng.', 'backup payment service, ready', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-12', 'lesson-audio-itops-b1-09', 'owner', 80.8, 88.8, 'Let us move fifty percent of checkout traffic to the backup service first and watch the success rate.', '[SRE] Hãy chuyển trước 50% lưu lượng thanh toán sang dịch vụ dự phòng rồi theo dõi tỷ lệ thành công.', 'move traffic, success rate', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-13', 'lesson-audio-itops-b1-09', 'owner', 88.8, 95.5, 'Payments on the backup gateway are finishing in less than one second with zero timeouts.', '[App Support] Các giao dịch qua cổng dự phòng đang hoàn tất dưới một giây và không có lỗi quá thời gian nào.', 'finishing, zero timeouts', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-14', 'lesson-audio-itops-b1-09', 'owner', 95.5, 102.6, 'Great, I am moving one hundred percent of payment traffic over until the main partner recovers.', '[SRE] Tuyệt, tôi chuyển toàn bộ 100% lưu lượng thanh toán sang cho tới khi đối tác chính phục hồi.', 'main partner, recovers', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-15', 'lesson-audio-itops-b1-09', 'owner', 102.6, 110.1, 'I also lowered the gateway timeout to eight seconds and added a safe limit on automatic retries.', '[SRE] Tôi cũng đã hạ thời gian chờ của cổng xuống tám giây và thêm giới hạn an toàn cho các lần thử lại tự động.', 'automatic retries', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-16', 'lesson-audio-itops-b1-09', 'owner', 110.1, 116.8, 'Support tickets already stopped coming in, and payment success is back to its normal level.', '[App Support] Phiếu hỗ trợ đã ngừng đổ về rồi, và tỷ lệ thanh toán thành công đã quay về mức bình thường.', 'payment success, normal level', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-17', 'lesson-audio-itops-b1-09', 'owner', 116.8, 123.9, 'Let us keep an eye on the partner status page before switching traffic back tomorrow morning.', '[SRE] Hãy theo dõi trang trạng thái của đối tác trước khi chuyển lưu lượng quay lại vào sáng mai.', 'keep an eye on, switching back', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-18', 'lesson-audio-itops-b1-09', 'owner', 123.9, 128.9, 'Agreed; having a tested backup gateway really saved our afternoon today.', '[App Support] Nhất trí; có sẵn cổng dự phòng đã được kiểm thử thực sự cứu nguy cho buổi chiều hôm nay.', 'saved our afternoon', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-10', 'owner', 'audio-itops-b1-10', 'B1 | 10. Running a Weekly Incident Review & Runbook Update (IT Ops)', 'A 2-minute B1 team operations meeting reviewing weekly incidents, reducing noisy alerts, improving step-by-step guides, and helping new engineers (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-1', 'lesson-audio-itops-b1-10', 'owner', 0, 8, 'Welcome to our Friday operations review; let us look calmly at the two incidents we handled this week.', '[Ops Manager] Chào mừng đến buổi rà soát vận hành thứ Sáu; cùng xem lại bình tĩnh hai sự cố ta xử lý tuần này nhé.', 'operations review, handled', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-2', 'lesson-audio-itops-b1-10', 'owner', 8, 14.7, 'Total uptime stayed above ninety nine percent, though Tuesday’s night alert took longer than expected.', '[SysAdmin] Tổng thời gian hoạt động vẫn trên 99%, nhưng cảnh báo đêm thứ Ba mất thời gian xử lý lâu hơn dự kiến.', 'total uptime, longer than expected', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-3', 'lesson-audio-itops-b1-10', 'owner', 14.7, 21, 'What slowed the response down on Tuesday when the queue server stopped processing jobs?', '[Ops Manager] Điều gì đã làm chậm phản hồi vào thứ Ba khi máy chủ hàng đợi ngừng xử lý tác vụ?', 'slowed down, processing jobs', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-4', 'lesson-audio-itops-b1-10', 'owner', 21, 29.4, 'First, our monitoring chat received nearly forty small warnings that night, so the real problem was easy to miss.', '[SysAdmin] Thứ nhất, nhóm chat giám sát nhận gần bốn mươi cảnh báo nhỏ đêm đó nên rất dễ bỏ sót sự cố thật.', 'small warnings, easy to miss', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-5', 'lesson-audio-itops-b1-10', 'owner', 29.4, 35.7, 'Second, the restart steps in our wiki were old after last month’s server upgrade.', '[SysAdmin] Thứ hai, các bước khởi động lại trên wiki đã cũ sau đợt nâng cấp máy chủ tháng trước.', 'restart steps, server upgrade', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-6', 'lesson-audio-itops-b1-10', 'owner', 35.7, 43.7, 'That is very clear feedback; noisy alerts tire out the on call team and slow down real fixes.', '[Ops Manager] Phản hồi rất rõ ràng; cảnh báo ồn ào làm đội trực mệt mỏi và làm chậm việc sửa lỗi thật.', 'noisy alerts, tire out', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-7', 'lesson-audio-itops-b1-10', 'owner', 43.7, 51.7, 'Which of those forty small warnings can we safely turn off or put into a daily summary email?', '[Ops Manager] Trong bốn mươi cảnh báo nhỏ đó, loại nào ta có thể tắt an toàn hoặc gom thành email tổng hợp hằng ngày?', 'turn off, daily summary', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-8', 'lesson-audio-itops-b1-10', 'owner', 51.7, 60.1, 'Short CPU jumps that last under thirty seconds never need to wake someone up at three in the morning.', '[SysAdmin] Các đợt tăng CPU ngắn dưới ba mươi giây không bao giờ cần đánh thức ai đó lúc ba giờ sáng.', 'CPU jumps, wake someone up', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-9', 'lesson-audio-itops-b1-10', 'owner', 60.1, 69.3, 'Agreed; let us wait until high CPU stays above eighty five percent for five minutes before calling the on call engineer.', '[Ops Manager] Nhất trí; hãy chờ CPU cao duy trì trên 85% suốt năm phút rồi mới gọi kỹ sư trực.', 'on call engineer, stays above', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-10', 'lesson-audio-itops-b1-10', 'owner', 69.3, 75.6, 'What about updating our incident guides so new shift engineers can follow them easily?', '[Ops Manager] Còn việc cập nhật hướng dẫn sự cố để các kỹ sư ca mới làm theo thật dễ dàng thì sao?', 'shift engineers, easily', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-11', 'lesson-audio-itops-b1-10', 'owner', 75.6, 82.7, 'I already rewrote the queue server guide with exact commands, expected results, and clear rollback steps.', '[SysAdmin] Tôi đã viết lại hướng dẫn máy chủ hàng đợi với câu lệnh chính xác, kết quả mong đợi và bước hoàn tác rõ ràng.', 'exact commands, expected results', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-12', 'lesson-audio-itops-b1-10', 'owner', 82.7, 89.8, 'Can we ask one of our newer engineers to test that guide on staging next Tuesday?', '[Ops Manager] Ta có thể nhờ một kỹ sư mới chạy thử hướng dẫn đó trên môi trường staging thứ Ba tới không?', 'newer engineers, test on staging', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-13', 'lesson-audio-itops-b1-10', 'owner', 89.8, 98.2, 'Great idea; if a new team member can follow every step smoothly, we know the document is really clear.', '[SysAdmin] Ý tuyệt vời; nếu thành viên mới làm theo trôi chảy từng bước thì ta biết tài liệu thực sự rõ ràng.', 'really clear, follow every step', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-14', 'lesson-audio-itops-b1-10', 'owner', 98.2, 104.1, 'Let us also link each monitoring alert directly to its matching guide page.', '[Ops Manager] Hãy gắn luôn đường dẫn trực tiếp từ mỗi cảnh báo giám sát tới trang hướng dẫn tương ứng.', 'link directly, matching guide', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-15', 'lesson-audio-itops-b1-10', 'owner', 104.1, 111.6, 'That saves important minutes during an urgent phone call because nobody has to search through old folders.', '[SysAdmin] Việc đó tiết kiệm những phút quan trọng trong cuộc gọi khẩn cấp vì không ai phải lục tìm thư mục cũ.', 'important minutes, urgent phone call', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-16', 'lesson-audio-itops-b1-10', 'owner', 111.6, 117.9, 'Before we finish, is there any maintenance or risky release planned for next week?', '[Ops Manager] Trước khi kết thúc, tuần tới có lịch bảo trì hay bản phát hành rủi ro nào không?', 'maintenance, planned', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-17', 'lesson-audio-itops-b1-10', 'owner', 117.9, 124.6, 'Only a normal security update on Wednesday evening, and backups are already checked and ready.', '[SysAdmin] Chỉ có một đợt cập nhật bảo mật bình thường tối thứ Tư, và các bản sao lưu đều đã kiểm tra sẵn sàng.', 'security update, checked and ready', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-18', 'lesson-audio-itops-b1-10', 'owner', 124.6, 131.3, 'Great work everyone; fewer noisy alerts and clearer guides will make next week much calmer.', '[Ops Manager] Cả đội làm rất tốt; ít cảnh báo nhiễu hơn và hướng dẫn rõ hơn sẽ giúp tuần tới nhẹ nhàng hơn nhiều.', 'much calmer', 17);
